package com.vandorlabs.neoforge.programmer;
import com.vandorlabs.neoforge.VandorLabsBootstrap;
import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import com.vandorlabs.neoforge.screen.NativeChipJournal;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.*;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
/** Actual private four-cell item/player path. Fixture acknowledgements carry only the current step. */
@EventBusSubscriber(modid="vandorlabs")
public final class ProgrammerWorldFixture {
 static final BlockPos SUPPORT=new BlockPos(0,96,0),ROOT=SUPPORT.north(),ACK=SUPPORT.east(4).north(8);
 static int step,checks;private static java.util.UUID actor;private static boolean toolObserved,toolSneak;private static ItemStack copyInput;private static final java.util.List<ItemStack> thrown=new java.util.ArrayList<>();
 static int finalStep(){return Boolean.getBoolean("vandorlabs.programmerGuideCheck")?3:17;}
 static boolean enabled(){return Boolean.getBoolean("vandorlabs.programmerWorldCheck")&&!Boolean.getBoolean("vandorlabs.programmerRenderMatrixCheck");}
 static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Programmer world step="+step+": "+why);}
 public record Ack(int step)implements CustomPacketPayload{static final Type<Ack> TYPE=new Type<>(ResourceLocation.parse("vandorlabs:programmer_world_ack"));public Type<? extends CustomPacketPayload> type(){return TYPE;}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration{
  @SubscribeEvent public static void payload(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent event){if(!enabled())return;if(!net.minecraft.core.registries.BuiltInRegistries.BLOCK.containsKey(ProgrammerCanonicalMode.ID))ProgrammerSettingsPayload.register(event);event.registrar("1").playToServer(Ack.TYPE,new StreamCodec<RegistryFriendlyByteBuf,Ack>(){public Ack decode(RegistryFriendlyByteBuf b){if(b.readableBytes()!=1)throw new IllegalArgumentException("Programmer fixture acknowledgement");int step=b.readUnsignedByte();if(step>16&&(step<64||step>66))throw new IllegalArgumentException("Programmer fixture step");return new Ack(step);}public void encode(RegistryFriendlyByteBuf b,Ack ack){b.writeByte(ack.step);}},(ack,context)->context.enqueueWork(()->{if(context.player() instanceof ServerPlayer player)ack(player,ack.step);}));}
 }
 @SubscribeEvent public static void clicked(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock event){if(enabled()&&(step==7||step==8)&&event.getEntity() instanceof ServerPlayer player&&player.getUUID().equals(actor)&&event.getHand()==InteractionHand.MAIN_HAND&&player.getMainHandItem().is(VandorLabsBootstrap.CONFIGURIZER.get())&&ProgrammerHostChecks.block().installed(player.serverLevel(),event.getPos())!=null){toolObserved=true;toolSneak=player.isShiftKeyDown();}}
 static ItemStack held(int step){return switch(step){case 0->new ItemStack(ProgrammerHostChecks.block(),2);case 1->NativeCredentialItems.dataChip(4).copyWithCount(2);case 2->{var result=NativeCredentialItems.dataChip(0).copyWithCount(2);var tag=new CompoundTag();tag.putString("ProgrammerPrivate","PRIVATE_PHYSICAL_ONLY");result.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));yield result;}case 12->NativeCredentialItems.dataChip(2);case 7,8->new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get());default->ItemStack.EMPTY;};}
 static double actorZ(int step){return step==1||step==2||step==10||step==11||step==12||step==15||step==16?-1.8:-3.5;}
 static Vec3 target(int step){return switch(step){case 0->new Vec3(.5,96.5,0);case 1->new Vec3(.625,96+16.02/16,-1+.7);case 2->new Vec3(28D/16,96+16.02/16,-1+8.75/16);case 10,12->new Vec3(3.5/16,96+16.02/16,-1+.7);case 11,15->new Vec3(28D/16,96+16.02/16,-1+.7);case 16->new Vec3(.625,96+16.02/16,-1+.7);case 5,6->{var plane=ProgrammerHostChecks.block().journalPlane();var p=plane.point(step==5?280:30,124);yield new Vec3(p.x,96+p.y,-1+p.z);}default->new Vec3(.4,96.55,-1);};}
 @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(!enabled()||!(event.getEntity() instanceof ServerPlayer player))return;ProgrammerCanonicalMode.validate();actor=player.getUUID();var level=player.serverLevel();level.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,player.getServer());level.getGameRules().getRule(GameRules.RULE_DOMOBSPAWNING).set(false,player.getServer());level.setDayTime(6000);level.setWeatherParameters(20000,0,false,false);for(int x=-4;x<=5;x++)for(int z=-5;z<=3;z++){level.setBlock(new BlockPos(x,95,z),Blocks.STONE.defaultBlockState(),3);for(int y=96;y<=100;y++)level.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}level.setBlock(SUPPORT,Blocks.STONE.defaultBlockState(),3);setup(player);System.out.println("[vandorlabs][programmer-world] setup PASS");}
 static void setup(ServerPlayer player){var level=player.serverLevel();toolObserved=false;if(step==4||step==14){level.setBlock(ACK,Blocks.NOTE_BLOCK.defaultBlockState().setValue(NoteBlock.NOTE,step),3);return;}player.setGameMode(GameType.SURVIVAL);player.setShiftKeyDown(false);if(step==16){player.getInventory().setItem(9,player.getMainHandItem());player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);}else if(step!=11){player.getInventory().clearContent();player.setItemInHand(InteractionHand.MAIN_HAND,held(step));}player.getInventory().selected=0;player.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);player.getAbilities().flying=false;player.onUpdateAbilities();for(int x=0;x<2;x++)level.setBlock(new BlockPos(x,97,-2),step==6?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),3);var target=step==9?new Vec3(1,97.1,-.5):target(step);double x=.5,y=96,z=actorZ(step),dx=target.x-x,dy=target.y-y-player.getEyeHeight(),dz=target.z-z;player.connection.teleport(x,y,z,(float)-Math.toDegrees(Math.atan2(dx,dz)),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz))));player.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(0));player.inventoryMenu.broadcastChanges();level.setBlock(ACK,Blocks.NOTE_BLOCK.defaultBlockState().setValue(NoteBlock.NOTE,step),3);System.out.println("[vandorlabs][programmer-world] ready step="+step+" held="+player.getMainHandItem());}
 static void ack(ServerPlayer player,int received){if(received>=64){need(ProgrammerCanonicalMode.enabled()&&actor.equals(player.getUUID())&&received==64+step&&step<3&&!player.isCreative()&&player.serverLevel().getBlockEntity(ROOT) instanceof NativeProgrammerEntity,"bounded canonical construction photograph request");var target=new Vec3(1,97,-.5);double dx=target.x-.5,dy=target.y-96-player.getEyeHeight(),dz=target.z+3.5;player.connection.teleport(.5,96,-3.5,(float)-Math.toDegrees(Math.atan2(dx,dz)),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz))));return;}need(actor.equals(player.getUUID())&&received==step&&!player.isCreative(),"exact actor/step/Survival");var level=player.serverLevel();need(level.getBlockEntity(ROOT) instanceof NativeProgrammerEntity,"sole installed root");var owner=(NativeProgrammerEntity)level.getBlockEntity(ROOT);need(owner.getBlockState().getValue(NativeProgrammerBlock.FACING)==Direction.NORTH,"actual facing");switch(step){case 0->{need(player.getMainHandItem().getCount()==1,"actual item consumes one");for(int part=0;part<4;part++){var pos=NativeProgrammerBlock.cell(ROOT,Direction.NORTH,part);need(level.getBlockState(pos).is(ProgrammerHostChecks.block())&&level.getBlockState(pos).getValue(NativeProgrammerBlock.PART)==part,"all four source cells");if(part>0)need(level.getBlockEntity(pos)==null,"member has no second owner");}}case 1->need(owner.getItem(0).getCount()==1&&NativeCredentialItems.company(owner.getItem(0))==4&&player.getMainHandItem().getCount()==1,"master socket sole owner");case 2->need(owner.getItem(1).getCount()==1&&player.getMainHandItem().getCount()==1,"input socket sole owner");case 3->need(player.containerMenu instanceof NativeProgrammerMenu menu&&menu.tile==owner,"ordinary body opens exact dedicated menu");case 4->{need(owner.getItem(1).isEmpty()&&owner.getItem(2).getCount()==1&&NativeChipJournal.journal(owner.getItem(2)),"actual editor Program consumes Input and owns Output");need(owner.journalView().journal.title.equals("Player journal")&&owner.journalView().journal.pages.size()==2,"all typed title/page text reaches authority");need(owner.getItem(2).getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getString("ProgrammerPrivate").equals("PRIVATE_PHYSICAL_ONLY"),"program preserves unrelated physical data");need(!owner.getUpdateTag(level.registryAccess()).toString().contains("PRIVATE_PHYSICAL_ONLY"),"public DTO excludes private envelope");need(player.containerMenu==player.inventoryMenu,"real menu closed");}case 5->need(owner.journalView().page==1,"actual journal Next advances");case 6->need(owner.journalView().page==1,"nearer wall refuses Previous");case 7,8->{need(player.containerMenu instanceof NativeProgrammerMenu menu&&menu.tile==owner,"held tool opens same dedicated dialog");need(toolObserved&&toolSneak==(step==8),"actual tool sneak state at use, before GUI releases keys");player.closeContainer();}case 9->need(owner.journalView()!=null&&owner.getItem(0).getCount()==1&&owner.getItem(2).getCount()==1,"rendering leaves physical ownership intact");case 10->{need(owner.getItem(2).isEmpty()&&NativeChipJournal.journal(player.getMainHandItem())&&player.getMainHandItem().getCount()==1,"actual empty-hand Output return");copyInput=player.getMainHandItem().copy();}case 11->need(player.getMainHandItem().isEmpty()&&ItemStack.matches(owner.getItem(1),copyInput),"returned complete journal reinserted as committed Input");case 12->need(player.getMainHandItem().isEmpty()&&NativeCredentialItems.company(owner.getItem(2))==2,"one blank target inserted in Output");case 13->need(player.containerMenu instanceof NativeProgrammerMenu menu&&menu.tile==owner,"Copy opens actual dedicated menu");case 14->{need(ItemStack.matches(owner.getItem(1),copyInput)&&owner.getItem(0).getCount()==1&&owner.getItem(2).isEmpty(),"Copy/quickmove/throw preserves Input and Master, drains Output");need(owner.draft().title().equals("Draft only"),"Copy keeps configured draft separate from committed Input");need(thrown.size()==1&&ItemStack.matches(thrown.getFirst(),copyInput),"vanilla menu throw owns exactly one complete copied journal");for(var stack:player.getInventory().items)need(stack.isEmpty(),"quick-moved copy no longer in player inventory");need(player.containerMenu==player.inventoryMenu,"actual Copy menu closed");}case 15->need(owner.getItem(1).isEmpty()&&ItemStack.matches(player.getMainHandItem(),copyInput),"actual committed Input return");case 16->{need(owner.getItem(0).isEmpty()&&owner.getItem(1).isEmpty()&&owner.getItem(2).isEmpty(),"all three physical sockets drained");need(player.getMainHandItem().getCount()==1&&NativeCredentialItems.company(player.getMainHandItem())==4&&ItemStack.matches(player.getInventory().getItem(9),copyInput),"sole returned Master and complete Input retained: handCount="+player.getMainHandItem().getCount()+" handCompany="+NativeCredentialItems.company(player.getMainHandItem())+" inputCount="+player.getInventory().getItem(9).getCount()+" expectedCount="+copyInput.getCount());}}step++;if(step<finalStep())setup(player);else{level.setBlock(ACK,Blocks.NOTE_BLOCK.defaultBlockState().setValue(NoteBlock.NOTE,finalStep()),3);System.out.println("[vandorlabs][programmer-world] server PASS checks="+checks);}}
 @SubscribeEvent public static void dropped(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(enabled()&&step==14&&event.getLevel() instanceof net.minecraft.server.level.ServerLevel&&event.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity entity){entity.setPickUpDelay(32767);thrown.add(entity.getItem().copy());}}
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent event){if(enabled()&&event.getEntity().getUUID().equals(actor)){need(step==finalStep(),"whole player/renderer path");System.out.println("[vandorlabs][programmer-world] logout PASS");}}
}
